EDITS = {'addons/lux/resources/lux_light_rig.gd': [('lines 103-104', 'var bake_mode: int = 0\n\n', "var bake_mode: int = 0\n## The range a STATIC lamp bakes with, when that is longer than the\n## `light_range` it claims live (0.80.0); 0 bakes at `light_range`. A lamp's\n## range is also the realtime claim it makes on every dynamic object it\n## reaches, so the live range stays short and the lightmap is lent this one\n## only while it bakes (`LuxLightLoader.stretch_bake_ranges`). 0 is not\n## saved, so a scene with no such row is byte-identical.\n@export_range(0.0, 60.0) var bake_range: float = 0.0\n\n")], 'addons/lux/runtime/lux_fixture_spawner.gd': [('lines 86-86', '\t\t# storefront carries it and nothing else does (0.56.0).\n', '\t\t# storefront carries it and nothing else does (0.56.0). And\n\t\t# `lux_bake_reach` (Zoo >= 1.134.0), the floor a baked row must\n\t\t# reach in the lightmap (0.80.0).\n'), ('lines 90-90', '\t\t\t"reach": float(marker_payload(mk, "lux_reach", 0.0))})\n', '\t\t\t"reach": float(marker_payload(mk, "lux_reach", 0.0)),\n\t\t\t"bake_reach": float(marker_payload(mk, "lux_bake_reach", 0.0))})\n')], 'addons/lux/runtime/lux_light_loader.gd': [('lines 1243-1244', '\t\t\tr.light_range = fluorescent_range(drop, float(a.get("reach", 0.0)))\n\t\t\t# Inverse-square falloff: at the default near-linear 1.0 the pool\n', '\t\t\tr.light_range = fluorescent_range(drop, float(a.get("reach", 0.0)))\n\t\t\t# AND WHAT IT BAKES WITH (0.80.0): a row that carries `bake_reach`\n\t\t\t# lends the lightmap a longer range than it claims live\n\t\t\t# (`fluorescent_bake_range`, `stretch_bake_ranges`).\n\t\t\tvar bake_reach := float(a.get("bake_reach", 0.0))\n\t\t\tif bake_reach > 0.0:\n\t\t\t\tr.bake_range = fluorescent_bake_range(drop, bake_reach, r.light_range)\n\t\t\t# Inverse-square falloff: at the default near-linear 1.0 the pool\n'), ('lines 1653-1654', "\t\t\treturn null   # 'sun' is owned by the preset/SkyMint; others skipped\n\n", '\t\t\treturn null   # \'sun\' is owned by the preset/SkyMint; others skipped\n\n\n## THE RANGE A BAKED ROW LENDS ITS LIGHTMAP (0.80.0): `hypot(drop,\n## bake_reach) + 0.75`, never under the live ``light_range``, and NOT under\n## `fluorescent_range`\'s clamp -- that clamp prices the realtime claim each\n## lamp makes on every mesh it reaches, which a static lamp\'s lightmap does\n## not make. Deli Counter (>= 0.279.0) stamps `bake_reach` as a row\'s lamp\n## spacing, so the light reaches the floor under the next lamp along.\n##\n## MEASURED on the walker\'s Restaurant Row level (seed 9205), the supermarket\'s\n## 50 rows at 4.85 m live, re-baked with the range scaled\n## (the factory\'s docs/findings/black_gondola_ends/range_arm.py): the frame\n## toward the coolers 38.5 -> 61.5 mean at x 1.6, the gondolas\' black end\n## (1, 1, 7) -> (34, 32, 25). This rule gives 7.61 m there (drop 4.1, spacing\n## 5.5), x 1.57.\nstatic func fluorescent_bake_range(drop: float, bake_reach: float, live: float) -> float:\n\tif drop <= 0.0 or bake_reach <= 0.0:\n\t\treturn 0.0\n\treturn maxf(sqrt(drop * drop + bake_reach * bake_reach) + 0.75, live)\n\n\n## Lend every static fluorescent lamp under ``scene_root`` its rig\'s\n## `bake_range`, for a lightmap bake (0.80.0). Returns what to give back --\n## ``[[lamp, live range], ...]`` -- for `restore_bake_ranges`, which the\n## baker calls before it saves: the saved scene keeps the live range, and a\n## loaded rig rebuilds its lamps from `light_range` in any case. A rig that\n## is not static, or carries no `bake_range`, is untouched.\nstatic func stretch_bake_ranges(scene_root: Node) -> Array:\n\tvar lent: Array = []\n\tif scene_root == null:\n\t\treturn lent\n\tfor n in scene_root.find_children("*", "Node3D", true, false):\n\t\tif not (n is LuxFluorescentRig):\n\t\t\tcontinue\n\t\tvar rig: LuxLightRig = (n as LuxFluorescentRig).rig\n\t\tif rig == null or rig.bake_mode != 1 or rig.bake_range <= rig.light_range:\n\t\t\tcontinue\n\t\tfor c in n.get_children():\n\t\t\tif c is SpotLight3D:\n\t\t\t\tlent.append([c, (c as SpotLight3D).spot_range])\n\t\t\t\t(c as SpotLight3D).spot_range = rig.bake_range\n\t\t\telif c is OmniLight3D:\n\t\t\t\tlent.append([c, (c as OmniLight3D).omni_range])\n\t\t\t\t(c as OmniLight3D).omni_range = rig.bake_range\n\treturn lent\n\n\n## Give back what `stretch_bake_ranges` lent. Returns how many lamps.\nstatic func restore_bake_ranges(lent: Array) -> int:\n\tvar n := 0\n\tfor e in lent:\n\t\tvar l: Variant = e[0]\n\t\tif not is_instance_valid(l):\n\t\t\tcontinue\n\t\tif l is SpotLight3D:\n\t\t\t(l as SpotLight3D).spot_range = float(e[1])\n\t\telif l is OmniLight3D:\n\t\t\t(l as OmniLight3D).omni_range = float(e[1])\n\t\tn += 1\n\treturn n\n\n')]}
NEW_FILES = {'tools/bake_reach_selftest.gd': 'extends SceneTree\n## A baked fluorescent row lends its lightmap a longer range than it claims live (0.80.0).\n##\n##     godot --headless --path lux --import\n##     godot --headless --path lux -s res://tools/bake_reach_selftest.gd\n##\n## Exit 0 = every case behaved. Exit 1 = a case failed (the message says\n## which). Exit 2 = could not run at all, which is never reported as a pass.\n##\n## Headless bakes nothing, so whether the store reads brighter is the frames\'\n## to show (the factory\'s docs/findings/black_gondola_ends/). What this holds:\n##\n##   * the rule: `hypot(drop, bake_reach) + 0.75`, past the live clamp, never\n##     under the live range, 0 without a `bake_reach`;\n##   * the SHIPPING path carries it: a marker\'s `lux_bake_reach` reaches the\n##     spawned rig\'s `bake_range`, and a marker without one has none -- the\n##     control that proves the check can tell the two apart;\n##   * the lamp\'s LIVE range is the rule it always was, with or without one;\n##   * `stretch_bake_ranges` lends a static rig its bake range and leaves a\n##     realtime rig and a rig without one alone; `restore_bake_ranges` gives\n##     every lamp back its live range.\n\nconst LOADER := "res://addons/lux/runtime/lux_light_loader.gd"\n\nvar _fails: int = 0\n\n\nfunc _initialize() -> void:\n\t_main()\n\n\nfunc _check(label: String, got: Variant, want: Variant) -> void:\n\tvar ok: bool = str(got) == str(want)\n\tif not ok:\n\t\t_fails += 1\n\tprint("  %s %s: %s%s" % ["ok  " if ok else "FAIL", label, str(got),\n\t\t"" if ok else "   (wanted %s)" % str(want)])\n\n\nfunc _near(label: String, got: float, want: float, tol: float) -> void:\n\tvar ok := absf(got - want) <= tol\n\tif not ok:\n\t\t_fails += 1\n\tprint("  %s %s: %.4f%s" % ["ok  " if ok else "FAIL", label, got,\n\t\t"" if ok else "   (wanted %.4f +/- %.4f)" % [want, tol]])\n\n\nfunc _range(rig: Node) -> float:\n\tfor c in rig.get_children():\n\t\tif c is SpotLight3D:\n\t\t\treturn (c as SpotLight3D).spot_range\n\t\tif c is OmniLight3D:\n\t\t\treturn (c as OmniLight3D).omni_range\n\treturn -1.0\n\n\nfunc _marker(parent: Node, nm: String, extras: Dictionary) -> void:\n\tvar mk := Node3D.new()\n\tmk.name = nm\n\tmk.set_meta(&"extras", extras)\n\tparent.add_child(mk)\n\n\nfunc _main() -> void:\n\tvar loader: Script = load(LOADER)\n\tif loader == null:\n\t\tpush_error("[bake_reach_selftest] could not load %s" % LOADER)\n\t\tquit(2)\n\t\treturn\n\tprint("bake reach selftest")\n\n\t# ------------------------------------------------------------ the rule\n\tvar want := sqrt(4.1 * 4.1 + 5.5 * 5.5) + 0.75\n\t_near("the supermarket\'s row: hypot(4.1, 5.5) + 0.75", loader.fluorescent_bake_range(4.1, 5.5, 4.85),\n\t\twant, 1e-4)\n\t_near("past the live clamp of 7.5", loader.fluorescent_bake_range(5.0, 7.0, 7.5),\n\t\tsqrt(25.0 + 49.0) + 0.75, 1e-4)\n\t_near("never under the live range", loader.fluorescent_bake_range(1.0, 1.0, 4.0), 4.0, 1e-4)\n\t_near("no bake_reach, none", loader.fluorescent_bake_range(4.1, 0.0, 4.85), 0.0, 1e-9)\n\t_near("no drop, none", loader.fluorescent_bake_range(0.0, 5.5, 4.0), 0.0, 1e-9)\n\n\t# ------------------------------------------------- the shipping path\n\tvar level := Node3D.new()\n\tget_root().add_child(level)\n\t_marker(level, "LuxEmit_fluorescent", {"lux_type": "fluorescent",\n\t\t"lux_anchor_id": "sales_floor_ceiling", "lux_slot": 0, "lux_drop": 4.1, "lux_bake_reach": 5.5})\n\t_marker(level, "LuxEmit_fluorescent_001", {"lux_type": "fluorescent",\n\t\t"lux_anchor_id": "stockroom_ceiling", "lux_slot": 0, "lux_drop": 4.1})\n\tvar res: Dictionary = LuxFixtureSpawner.spawn(level)\n\t_check("the spawner made both rigs", int(res.get("count", 0)), 2)\n\tawait process_frame\n\tvar box: Node = level.get_node_or_null(NodePath(LuxFixtureSpawner.CONTAINER))\n\tif box == null:\n\t\tpush_error("[bake_reach_selftest] the spawner made no container")\n\t\tquit(2)\n\t\treturn\n\tvar bakes: Array = []\n\tvar lives: Array = []\n\tvar rigs: Array = []\n\tfor rig in box.get_children():\n\t\tif rig is LuxFluorescentRig:\n\t\t\trigs.append(rig)\n\t\t\tbakes.append(snappedf((rig as LuxFluorescentRig).rig.bake_range, 0.0001))\n\t\t\tlives.append(snappedf(_range(rig), 0.0001))\n\tbakes.sort()\n\t_check("a marker\'s lux_bake_reach reaches the rig; one without has none", bakes,\n\t\t[0.0, snappedf(want, 0.0001)])\n\t_check("the live range is the rule it always was, with or without", lives, [4.85, 4.85])\n\n\t# ------------------------------------------------- the lend and the return\n\tvar lent: Array = loader.stretch_bake_ranges(level)\n\t_check("a realtime rig is not lent anything", lent.size(), 0)\n\tfor rig in rigs:\n\t\t(rig as LuxFluorescentRig).rig.bake_mode = 1\n\tlent = loader.stretch_bake_ranges(level)\n\t_check("a static rig with a bake range is lent it; one without is not", lent.size(), 1)\n\tvar during: Array = []\n\tfor rig in rigs:\n\t\tduring.append(snappedf(_range(rig), 0.0001))\n\tduring.sort()\n\t_check("while baking", during, [4.85, snappedf(want, 0.0001)])\n\t_check("every lamp given back", loader.restore_bake_ranges(lent), 1)\n\tvar after: Array = []\n\tfor rig in rigs:\n\t\tafter.append(snappedf(_range(rig), 0.0001))\n\t_check("after the bake, the live ranges", after, [4.85, 4.85])\n\n\tprint("bake reach selftest: %s" % ("PASS" if _fails == 0 else "%d FAILED" % _fails))\n\tquit(0 if _fails == 0 else 1)\n', 'tools/bake_reach_selftest.gd.uid': 'uid://b2cf6ql4vg8mr\n'}
CHANGELOG = '## [0.80.0] - a baked row lends its lightmap a longer range than it claims live\n\nThe walker, 2026-10-26, in a supermarket: "far too dark in teh super market". Measured on the walker\'s level (the\nfactory\'s docs/findings/black_gondola_ends/):\n\n- The supermarket\'s 50 lamps are baked statics at a 4.85 m range: drop + 0.75, written against the realtime claim\n  each lamp makes on every mesh it reaches.\n- Re-baked with the range scaled, the frame toward the coolers went 38.5 -> 61.5 mean at x 1.6, 68.9 at x 2.0.\n  The gondolas\' black ends went (1, 1, 7) -> (34, 32, 25). The control reproduced the shipped frame to the digit.\n- A static lamp\'s lightmap makes no per-mesh claim, but its live range still does: on every dynamic object, and so\n  on every player in the room. So the long range is the bake\'s alone.\n\n### Added\n- **`LuxLightRig.bake_range`**, the range a STATIC lamp bakes with when that is longer than its `light_range`. At 0\n  it bakes at `light_range`. 0 is not saved, so a scene with no such row is byte-identical.\n- **`LuxLightLoader.fluorescent_bake_range(drop, bake_reach, live)`**: `hypot(drop, bake_reach) + 0.75`.\n  - It is never under the live range, and NOT under `fluorescent_range`\'s 7.5 clamp, which prices a realtime claim.\n  - Deli Counter (>= 0.279.0) stamps `bake_reach` as a row\'s lamp spacing, so the light reaches the floor under the\n    next lamp along.\n  - It gives 7.61 m for the supermarket\'s rows (drop 4.1, spacing 5.5), x 1.57.\n- A fluorescent anchor\'s `bake_reach`, and a marker\'s `lux_bake_reach` (Zoo >= 1.134.0), set its rig\'s\n  `bake_range`. `LuxFixtureSpawner` hands it on as it hands on `lux_reach`. The live range is the rule it always was.\n- **`LuxLightLoader.stretch_bake_ranges(scene_root)`** lends every static fluorescent lamp with a `bake_range` that\n  range, for a lightmap bake. It returns what to give back.\n- **`restore_bake_ranges(lent)`** gives it back, before the baker saves. Level Factory\'s bake (>= 0.261.0) calls\n  both, as it calls `add_bake_fills`. A loaded rig rebuilds its lamps from `light_range` whatever was saved, but the\n  saved scene keeps the live range so an instrument reading it reads the truth.\n\n### Tests\n- `tools/bake_reach_selftest.gd`:\n  - the rule, past the clamp, never under the live range, none without;\n  - a marker\'s `lux_bake_reach` reaches the spawned rig and one without has none (the control);\n  - the live range unchanged with or without;\n  - a realtime rig lent nothing, a static one lent its bake range and one without none;\n  - every lamp given back.\n\n  Fails on 0.79.0, which has no `fluorescent_bake_range`. All 28 selftests exit 0 on 0.80.0.\n\n### Not measured here\nHeadless bakes nothing. The bake through this path, and the frames of the store it makes, are the factory\'s to\nrecord (docs/findings/black_gondola_ends/).\n\n'
OLD_VERSION, NEW_VERSION = 'Lux 0.79.0', 'Lux 0.80.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: lux/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: lux/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: lux/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: lux/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    head = b"# Changelog\n\n"
    if b"\r\n" in craw or not craw.startswith(head + b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(head + CHANGELOG.encode("utf-8") + craw[len(head):])
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in lux/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
